enum DriveErrorKind {
  inactivePlan,
  featureDenied,
  quotaExceeded,
  providerReauthRequired,
  preconditionFailed,
  operationFingerprintMismatch,
  transient,
  rateLimited,
  invalidResponse,
  notFound,
  permanent,
}

final class DriveProviderException implements Exception {
  const DriveProviderException(
    this.kind,
    this.message, {
    this.retryAfter,
    this.providerOperationId,
    this.statusCode,
    this.cause,
  });

  final DriveErrorKind kind;
  final String message;
  final Duration? retryAfter;
  final String? providerOperationId;
  final int? statusCode;
  final Object? cause;

  bool get retryable =>
      kind == DriveErrorKind.transient || kind == DriveErrorKind.rateLimited;
  bool get requiresReauth => kind == DriveErrorKind.providerReauthRequired;

  @override
  String toString() => 'DriveProviderException($kind, $message)';
}

final class DriveResult<T> {
  const DriveResult.ok(this.value) : error = null;
  const DriveResult.failure(this.error) : value = null;

  final T? value;
  final DriveProviderException? error;
  bool get isOk => error == null;
}

/// Transport seam for external products. No stock implementation is selected
/// implicitly; hosts register providers explicitly against their own account.
abstract interface class RemoteDriveProvider {
  String get providerId;
  DriveCapabilities get capabilities;

  Future<DriveResult<List<RemoteDriveItem>>> list(DriveListRequest request);
  Future<DriveResult<RemoteDriveItem>> get(
    DriveMountScope scope,
    DrivePath path,
  );
  Future<DriveResult<RemoteDriveDownload>> download(
    DriveMountScope scope,
    DrivePath path,
  );
  Future<DriveResult<RemoteDriveItem>> upload(DriveUploadRequest request);
  Future<DriveResult<RemoteDriveItem>> delete(DriveDeleteRequest request);
  Future<DriveResult<DriveChangesPage>> changes(DriveChangesRequest request);
}

enum DriveSyncStatus {
  localOnly,
  syncing,
  synced,
  conflict,
  planInactive,
  quotaExceeded,
  providerReauthRequired,
  permanentError,
}

/// Serializable state suitable for the existing Files/Recent Surfaces model.
const _errorStatuses = <DriveErrorKind, DriveSyncStatus>{
  DriveErrorKind.inactivePlan: DriveSyncStatus.planInactive,
  DriveErrorKind.featureDenied: DriveSyncStatus.planInactive,
  DriveErrorKind.quotaExceeded: DriveSyncStatus.quotaExceeded,
  DriveErrorKind.providerReauthRequired: DriveSyncStatus.providerReauthRequired,
  DriveErrorKind.preconditionFailed: DriveSyncStatus.conflict,
  DriveErrorKind.permanent: DriveSyncStatus.permanentError,
  DriveErrorKind.invalidResponse: DriveSyncStatus.permanentError,
  DriveErrorKind.operationFingerprintMismatch: DriveSyncStatus.permanentError,
};

final class DriveSyncState {
  const DriveSyncState({
    required this.status,
    required this.dirty,
    this.localRevision,
    this.remoteRevision,
    this.baseRevision,
    this.operationId,
    this.providerOperationId,
    this.providerDetails,
    this.retryAt,
    this.lastSyncedAt,
  });

  const DriveSyncState.localOnly([String? reason])
    : status = DriveSyncStatus.localOnly,
      dirty = false,
      localRevision = null,
      remoteRevision = null,
      baseRevision = null,
      operationId = null,
      providerOperationId = null,
      providerDetails = reason,
      retryAt = null,
      lastSyncedAt = null;

  final DriveSyncStatus status;
  final bool dirty;
  final String? localRevision;
  final String? remoteRevision;
  final String? baseRevision;
  final String? operationId;
  final String? providerOperationId;
  final String? providerDetails;
  final DateTime? retryAt;
  final DateTime? lastSyncedAt;

  DriveSyncState fromError(DriveProviderException error, {DateTime? now}) {
    final status =
        _errorStatuses[error.kind] ??
        (dirty ? DriveSyncStatus.syncing : DriveSyncStatus.permanentError);
    return DriveSyncState(
      status: status,
      dirty: dirty,
      localRevision: localRevision,
      remoteRevision: remoteRevision,
      baseRevision: baseRevision,
      operationId: operationId,
      providerOperationId: error.providerOperationId,
      providerDetails: error.message,
      retryAt: error.retryAfter == null || now == null
          ? null
          : now.add(error.retryAfter!),
      lastSyncedAt: lastSyncedAt,
    );
  }
}

String cryptoSha256(List<int> bytes) => sha256.convert(bytes).toString();

/// Stable payload fingerprint used for crash/restart idempotency. The auth
/// generation is deliberately excluded so retrying the SAME user operation
/// after reconnect is recognizable; stale writers are fenced separately.
String driveOperationFingerprint(DriveUploadRequest request) => sha256
    .convert(
      utf8.encode(
        '${request.scope.mountKey}\n${request.path.collisionKey}\n${request.sha256}\n${request.baseRevision ?? ''}',
      ),
    )
    .toString();

import 'dart:convert';
import 'dart:typed_data';

import 'drive_contract.dart';

/// Durable self-contained mutation. Bytes are stored with the operation so a
/// later local edit cannot change the payload retried under the same key.
final class DriveOperationRecord {
  const DriveOperationRecord({
    required this.operationId,
    required this.path,
    required this.bytes,
    required this.sha256,
    required this.fingerprint,
    required this.baseRevision,
    required this.localRevision,
    required this.authGeneration,
    required this.createdAt,
    this.delete = false,
  });

  final String operationId;
  final DrivePath path;
  final Uint8List bytes;
  final String sha256;
  final String fingerprint;
  final String? baseRevision;
  final int localRevision;
  final int authGeneration;
  final DateTime createdAt;
  final bool delete;

  DriveOperationRecord rebase(String? revision) => DriveOperationRecord(
    operationId: operationId,
    path: path,
    bytes: bytes,
    sha256: sha256,
    fingerprint: fingerprint,
    baseRevision: revision,
    localRevision: localRevision,
    authGeneration: authGeneration,
    createdAt: createdAt,
    delete: delete,
  );

  Map<String, Object?> toJson() => {
    'operationId': operationId,
    'path': path.absolute,
    'bytes': base64Encode(bytes),
    'sha256': sha256,
    'fingerprint': fingerprint,
    'baseRevision': baseRevision,
    'localRevision': localRevision,
    'authGeneration': authGeneration,
    'createdAt': createdAt.toUtc().toIso8601String(),
    'delete': delete,
  };

  factory DriveOperationRecord.fromJson(Map<String, Object?> json) {
    final path = DrivePath.parse(json['path']! as String);
    final bytes = Uint8List.fromList(base64Decode(json['bytes']! as String));
    final sha = json['sha256']! as String;
    if (cryptoSha256(bytes) != sha) {
      throw const FormatException('pending drive operation hash mismatch');
    }
    return DriveOperationRecord(
      operationId: json['operationId']! as String,
      path: path,
      bytes: bytes,
      sha256: sha,
      fingerprint: json['fingerprint']! as String,
      baseRevision: json['baseRevision'] as String?,
      localRevision: json['localRevision']! as int,
      authGeneration: json['authGeneration']! as int,
      createdAt: DateTime.parse(json['createdAt']! as String).toUtc(),
      delete: json['delete']! as bool,
    );
  }
}

final class DriveFileState {
  const DriveFileState({
    required this.collisionKey,
    required this.localRevision,
    this.localSha256,
    this.remoteRevision,
    this.remoteSha256,
    this.status = DriveSyncStatus.localOnly,
    this.dirty = false,
    this.providerDetails,
    this.retryAt,
    this.lastSyncedAt,
  });

  final String collisionKey;
  final int localRevision;
  final String? localSha256;
  final String? remoteRevision;
  final String? remoteSha256;
  final DriveSyncStatus status;
  final bool dirty;
  final String? providerDetails;
  final DateTime? retryAt;
  final DateTime? lastSyncedAt;

  DriveFileState copyWith({
    int? localRevision,
    String? localSha256,
    String? remoteRevision,
    String? remoteSha256,
    DriveSyncStatus? status,
    bool? dirty,
    String? providerDetails,
    DateTime? retryAt,
    DateTime? lastSyncedAt,
  }) => DriveFileState(
    collisionKey: collisionKey,
    localRevision: localRevision ?? this.localRevision,
    localSha256: localSha256 ?? this.localSha256,
    remoteRevision: remoteRevision ?? this.remoteRevision,
    remoteSha256: remoteSha256 ?? this.remoteSha256,
    status: status ?? this.status,
    dirty: dirty ?? this.dirty,
    providerDetails: providerDetails ?? this.providerDetails,
    retryAt: retryAt ?? this.retryAt,
    lastSyncedAt: lastSyncedAt ?? this.lastSyncedAt,
  );

  Map<String, Object?> toJson() => {
    'collisionKey': collisionKey,
    'localRevision': localRevision,
    'localSha256': localSha256,
    'remoteRevision': remoteRevision,
    'remoteSha256': remoteSha256,
    'status': status.name,
    'dirty': dirty,
    'providerDetails': providerDetails,
    'retryAt': retryAt?.toUtc().toIso8601String(),
    'lastSyncedAt': lastSyncedAt?.toUtc().toIso8601String(),
  };

  factory DriveFileState.fromJson(Map<String, Object?> json) => DriveFileState(
    collisionKey: json['collisionKey']! as String,
    localRevision: json['localRevision']! as int,
    localSha256: json['localSha256'] as String?,
    remoteRevision: json['remoteRevision'] as String?,
    remoteSha256: json['remoteSha256'] as String?,
    status: DriveSyncStatus.values.byName(json['status']! as String),
    dirty: json['dirty']! as bool,
    providerDetails: json['providerDetails'] as String?,
    retryAt: json['retryAt'] is String
        ? DateTime.parse(json['retryAt']! as String).toUtc()
        : null,
    lastSyncedAt: json['lastSyncedAt'] is String
        ? DateTime.parse(json['lastSyncedAt']! as String).toUtc()
        : null,
  );
}

/// Atomic browser-store envelope. [storageRevision] is the CAS version,
/// incremented by the store on every successful write.
final class DriveWorkspaceSnapshot {
  const DriveWorkspaceSnapshot({
    required this.scopeKey,
    required this.storageRevision,
    required this.nextLocalRevision,
    required this.files,
    required this.pending,
    this.cursor,
  });

  factory DriveWorkspaceSnapshot.empty(String scopeKey) =>
      DriveWorkspaceSnapshot(
        scopeKey: scopeKey,
        storageRevision: 0,
        nextLocalRevision: 1,
        files: const {},
        pending: const [],
      );

  static const schemaVersion = 1;

  final String scopeKey;
  final int storageRevision;
  final int nextLocalRevision;
  final Map<String, DriveFileState> files;
  final List<DriveOperationRecord> pending;
  final String? cursor;

  DriveWorkspaceSnapshot copyWith({
    int? storageRevision,
    int? nextLocalRevision,
    Map<String, DriveFileState>? files,
    List<DriveOperationRecord>? pending,
    String? cursor,
  }) => DriveWorkspaceSnapshot(
    scopeKey: scopeKey,
    storageRevision: storageRevision ?? this.storageRevision,
    nextLocalRevision: nextLocalRevision ?? this.nextLocalRevision,
    files: files ?? this.files,
    pending: pending ?? this.pending,
    cursor: cursor ?? this.cursor,
  );

  Map<String, Object?> payloadJson() => {
    'schemaVersion': schemaVersion,
    'scopeKey': scopeKey,
    'nextLocalRevision': nextLocalRevision,
    'files': {
      for (final entry in files.entries) entry.key: entry.value.toJson(),
    },
    'pending': pending.map((operation) => operation.toJson()).toList(),
    'cursor': cursor,
  };

  factory DriveWorkspaceSnapshot.fromPayload(
    Map<String, Object?> json, {
    required int storageRevision,
  }) {
    if (json['schemaVersion'] != schemaVersion) {
      throw const FormatException('unsupported drive snapshot schema');
    }
    final files = <String, DriveFileState>{};
    final rawFiles = json['files']! as Map;
    for (final entry in rawFiles.entries) {
      files[entry.key as String] = DriveFileState.fromJson(
        (entry.value as Map).cast<String, Object?>(),
      );
    }
    return DriveWorkspaceSnapshot(
      scopeKey: json['scopeKey']! as String,
      storageRevision: storageRevision,
      nextLocalRevision: json['nextLocalRevision']! as int,
      files: files,
      pending: (json['pending']! as List)
          .map(
            (raw) => DriveOperationRecord.fromJson(
              (raw as Map).cast<String, Object?>(),
            ),
          )
          .toList(),
      cursor: json['cursor'] as String?,
    );
  }
}

final class DriveStoreConcurrencyException implements Exception {
  const DriveStoreConcurrencyException(this.scopeKey);
  final String scopeKey;
}

abstract interface class DriveSyncStore {
  Future<DriveWorkspaceSnapshot> load(String scopeKey);

  /// Atomically compares [expectedStorageRevision] and persists the payload.
  /// Implementations must clone bytes/maps so callers cannot mutate history.
  Future<DriveWorkspaceSnapshot> save(
    DriveWorkspaceSnapshot snapshot, {
    required int expectedStorageRevision,
  });
}

final class MemoryDriveSyncStore implements DriveSyncStore {
  final Map<String, Map<String, Object?>> _records = {};

  @override
  Future<DriveWorkspaceSnapshot> load(String scopeKey) async {
    final record = _records[scopeKey];
    if (record == null) return DriveWorkspaceSnapshot.empty(scopeKey);
    final revision = record['storageRevision']! as int;
    final payload = (record['payload']! as Map).cast<String, Object?>();
    return DriveWorkspaceSnapshot.fromPayload(
      _clone(payload),
      storageRevision: revision,
    );
  }

  @override
  Future<DriveWorkspaceSnapshot> save(
    DriveWorkspaceSnapshot snapshot, {
    required int expectedStorageRevision,
  }) async {
    final current =
        _records[snapshot.scopeKey]?['storageRevision'] as int? ?? 0;
    if (current != expectedStorageRevision ||
        snapshot.storageRevision != expectedStorageRevision) {
      throw DriveStoreConcurrencyException(snapshot.scopeKey);
    }
    final revision = expectedStorageRevision + 1;
    final payload = _clone(snapshot.payloadJson());
    _records[snapshot.scopeKey] = {
      'storageRevision': revision,
      'payload': payload,
    };
    return DriveWorkspaceSnapshot.fromPayload(
      _clone(payload),
      storageRevision: revision,
    );
  }

  static Map<String, Object?> _clone(Map<String, Object?> value) =>
      (jsonDecode(jsonEncode(value)) as Map).cast<String, Object?>();
}

import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';

import '../env/execution_env.dart';
import '../product/fa_product_config.dart';
import '../session/session_record.dart';
import '../session/session_repo.dart';
import '../session/session_storage.dart';
import 'drive_contract.dart';
import 'session_sync_contract.dart';

/// Append-only JSONL tree synchronizer. Local files/outbox are authoritative
/// while offline; remote revisions are conditional and record ids, never
/// mtimes, drive the three-way merge.
final class CloudSessionSynchronizer {
  CloudSessionSynchronizer({
    required this.provider,
    required this.store,
    required this.localRepo,
    required this.env,
    required this.scope,
    this.remoteReadTimeout = const Duration(seconds: 12),
    String Function()? operationId,
  }) : operationId = operationId ?? _operationId;

  final RemoteSessionProvider provider;
  final CloudSessionSyncStore store;
  final SessionRepo localRepo;
  final ExecutionEnv env;
  final CloudSessionScope scope;
  final Duration remoteReadTimeout;
  final String Function() operationId;
  final Map<String, Future<void>> _dirtyChains = {};
  Object? lastDirtyError;

  /// Queues the latest complete local JSONL bytes. Callers may fire-and-forget
  /// this after the local append; [settle] makes the durable boundary explicit
  /// in tests and background flush scheduling.
  Future<void> markDirty(SessionMetadata metadata, {String? parentSessionId}) {
    final previous = _dirtyChains[metadata.id] ?? Future<void>.value();
    final result = previous.then(
      (_) => _markDirtyNow(metadata, parentSessionId),
    );
    _dirtyChains[metadata.id] = result.catchError((Object error) {
      lastDirtyError = error;
    });
    return result;
  }

  Future<void> settle() async {
    await Future.wait(_dirtyChains.values);
    final error = lastDirtyError;
    if (error != null) throw error;
  }

  Future<void> _markDirtyNow(
    SessionMetadata metadata,
    String? parentSessionId,
  ) async {
    final bytes = (await env.readBinaryFile(metadata.path)).getOrThrow();
    _validateDocument(bytes, expectedId: metadata.id);
    var snapshot = await store.load(scope.scopeKey);
    final parent = parentSessionId ?? _parentId(snapshot, metadata);
    // Coalesce not-yet-attempted writes for this session. Each operation keeps
    // its own bytes/fingerprint; an in-flight retry keeps its original key.
    final pending = snapshot.pending
        .where((op) => op.sessionId != metadata.id || op.delete)
        .toList();
    pending.add(
      CloudSessionOperation(
        sessionId: metadata.id,
        parentSessionId: parent,
        localPath: metadata.path,
        bytes: bytes,
        operationId: operationId(),
        baseRevision: snapshot.remoteRevisions[metadata.id],
        authGeneration: scope.identity.authGeneration,
        createdAt: DateTime.now().toUtc(),
      ),
    );
    final paths = {...snapshot.localPaths, metadata.id: metadata.path};
    await store.save(
      snapshot.copyWith(pending: pending, localPaths: paths),
      expectedStorageRevision: snapshot.storageRevision,
    );
  }

  Future<CloudSessionSnapshot> enqueueRemoteDelete(
    SessionMetadata metadata,
  ) async {
    var snapshot = await store.load(scope.scopeKey);
    snapshot = await store.save(
      snapshot.copyWith(
        pending: [
          ...snapshot.pending,
          CloudSessionOperation(
            sessionId: metadata.id,
            parentSessionId: null,
            localPath: metadata.path,
            bytes: Uint8List(0),
            operationId: operationId(),
            baseRevision: snapshot.remoteRevisions[metadata.id],
            authGeneration: scope.identity.authGeneration,
            createdAt: DateTime.now().toUtc(),
            delete: true,
          ),
        ],
      ),
      expectedStorageRevision: snapshot.storageRevision,
    );
    return snapshot;
  }

  Future<CloudSessionSnapshot> flush(CloudIdentity identity) async {
    _checkIdentity(identity);
    await settle();
    var snapshot = await store.load(scope.scopeKey);
    while (snapshot.pending.isNotEmpty) {
      final operation = snapshot.pending.first;
      if (operation.authGeneration != identity.authGeneration) {
        throw const DriveProviderException(
          DriveErrorKind.providerReauthRequired,
          'cloud session operation is fenced by auth generation',
        );
      }
      final result = operation.delete
          ? await provider.delete(
              scope,
              operation.sessionId,
              operation.operationId,
              operation.baseRevision,
              identity.authGeneration,
            )
          : await provider.upload(
              CloudSessionUpload(
                scope: scope,
                sessionId: operation.sessionId,
                parentSessionId: operation.parentSessionId,
                bytes: operation.bytes,
                operationId: operation.operationId,
                baseRevision: operation.baseRevision,
                authGeneration: identity.authGeneration,
              ),
            );
      if (!result.isOk) {
        final error = result.error!;
        if (error.kind == DriveErrorKind.preconditionFailed &&
            !operation.delete) {
          final remote = await provider.download(scope, operation.sessionId);
          if (!remote.isOk) throw remote.error!;
          final merged = mergeSessionJsonl(
            operation.bytes,
            remote.value!.bytes,
            parentSessionPath: snapshot.localPaths[operation.parentSessionId],
            preferRemoteLeaf: false,
          );
          final replacement = operation.copyWith(
            bytes: merged,
            operationId: operationId(),
            baseRevision: remote.value!.record.revision,
            authGeneration: identity.authGeneration,
          );
          final pending = [...snapshot.pending]..[0] = replacement;
          snapshot = await store.save(
            snapshot.copyWith(pending: pending),
            expectedStorageRevision: snapshot.storageRevision,
          );
          await _writeIfCurrent(replacement, operation.bytes);
          continue;
        }
        throw error;
      }
      final pending = [...snapshot.pending]..removeAt(0);
      final revisions = {
        ...snapshot.remoteRevisions,
        operation.sessionId: result.value!.revision,
      };
      snapshot = await store.save(
        snapshot.copyWith(pending: pending, remoteRevisions: revisions),
        expectedStorageRevision: snapshot.storageRevision,
      );
    }
    return snapshot;
  }

  /// Pulls parent documents before forks. Timeout/failure on one remote read
  /// never rewrites or drops local pending bytes; successfully read documents
  /// still advance and the first error is surfaced after the local CAS.
  Future<CloudSessionSnapshot> pull(CloudIdentity identity) async {
    _checkIdentity(identity);
    await settle();
    var snapshot = await store.load(scope.scopeKey);
    snapshot = await _indexLocalPaths(snapshot);
    final records = <CloudSessionRemoteRecord>[];
    String? cursor;
    do {
      final page = await provider.list(scope, cursor);
      if (!page.isOk) throw page.error!;
      records.addAll(page.value!.records);
      cursor = page.value!.hasMore ? page.value!.nextCursor : null;
    } while (cursor != null);

    final ordered = _parentsFirst(records.where((record) => !record.deleted));
    Object? firstReadError;
    for (final record in ordered) {
      if (snapshot.pending.any((op) => op.sessionId == record.sessionId)) {
        continue;
      }
      if (_alreadyMaterialized(snapshot, record)) continue;
      try {
        final download = await provider
            .download(scope, record.sessionId)
            .timeout(remoteReadTimeout);
        if (!download.isOk) throw download.error!;
        final remoteBytes = download.value!.bytes;
        _validateDocument(remoteBytes, expectedId: record.sessionId);
        if (record.sha256 != null &&
            cryptoSha256(remoteBytes) != record.sha256) {
          throw const DriveProviderException(
            DriveErrorKind.invalidResponse,
            'cloud session bytes do not match provider hash',
          );
        }
        snapshot = await _materialize(snapshot, record, remoteBytes);
      } catch (error) {
        firstReadError ??= error;
      }
    }
    snapshot = await store.save(
      snapshot.copyWith(cursor: cursor),
      expectedStorageRevision: snapshot.storageRevision,
    );
    if (firstReadError != null) throw firstReadError;
    return snapshot;
  }

  Future<SessionMetadata?> localMetadata(String sessionId) async {
    final sessions = await localRepo.list();
    for (final metadata in sessions) {
      if (metadata.id == sessionId) return metadata;
    }
    return null;
  }

  Future<CloudSessionSnapshot> _materialize(
    CloudSessionSnapshot snapshot,
    CloudSessionRemoteRecord record,
    Uint8List remoteBytes,
  ) async {
    final localPath = snapshot.localPaths[record.sessionId];
    var bytes = remoteBytes;
    if (localPath != null && (await env.exists(localPath)).getOrThrow()) {
      final localBytes = (await env.readBinaryFile(localPath)).getOrThrow();
      bytes = mergeSessionJsonl(
        localBytes,
        remoteBytes,
        parentSessionPath: _localParentPath(snapshot, record),
        preferRemoteLeaf: true,
      );
    } else {
      bytes = _rewriteParent(remoteBytes, _localParentPath(snapshot, record));
    }
    var path = localPath;
    if (path == null) {
      final header = sessionDocumentHeader(bytes);
      final parentPath = _localParentPath(snapshot, record);
      final created = await localRepo.create(
        JsonlSessionCreateOptions(
          cwd: header.cwd,
          id: record.sessionId,
          parentSessionPath: parentPath,
          metadata: header.metadata,
        ),
      );
      path = (await created.getMetadata()).path;
    }
    (await env.createDir(_parentPath(path))).getOrThrow();
    (await env.writeBinaryFile(path, bytes)).getOrThrow();
    final revisions = {
      ...snapshot.remoteRevisions,
      record.sessionId: record.revision,
    };
    final paths = {...snapshot.localPaths, record.sessionId: path};
    return store.save(
      snapshot.copyWith(remoteRevisions: revisions, localPaths: paths),
      expectedStorageRevision: snapshot.storageRevision,
    );
  }

  bool _alreadyMaterialized(
    CloudSessionSnapshot snapshot,
    CloudSessionRemoteRecord record,
  ) =>
      snapshot.remoteRevisions[record.sessionId] == record.revision &&
      snapshot.localPaths.containsKey(record.sessionId);

  Future<CloudSessionSnapshot> _indexLocalPaths(
    CloudSessionSnapshot snapshot,
  ) async {
    final paths = <String, String>{
      for (final metadata in await localRepo.list()) metadata.id: metadata.path,
    };
    if (_samePaths(paths, snapshot.localPaths)) return snapshot;
    return store.save(
      snapshot.copyWith(localPaths: paths),
      expectedStorageRevision: snapshot.storageRevision,
    );
  }

  bool _samePaths(Map<String, String> a, Map<String, String> b) {
    if (a.length != b.length) return false;
    for (final entry in a.entries) {
      if (b[entry.key] != entry.value) return false;
    }
    return true;
  }

  Future<void> _writeIfCurrent(
    CloudSessionOperation operation,
    Uint8List previousBytes,
  ) async {
    if (!(await env.exists(operation.localPath)).getOrThrow()) return;
    final live = (await env.readBinaryFile(operation.localPath)).getOrThrow();
    if (cryptoSha256(live) != cryptoSha256(previousBytes)) return;
    (await env.writeBinaryFile(
      operation.localPath,
      operation.bytes,
    )).getOrThrow();
  }

  void _checkIdentity(CloudIdentity identity) {
    if (!scope.accepts(identity)) {
      throw const DriveProviderException(
        DriveErrorKind.providerReauthRequired,
        'cloud session identity/auth generation is stale',
      );
    }
  }

  String? _parentId(CloudSessionSnapshot snapshot, SessionMetadata metadata) {
    for (final entry in snapshot.localPaths.entries) {
      if (entry.value == metadata.parentSessionPath) return entry.key;
    }
    return null;
  }

  String? _localParentPath(
    CloudSessionSnapshot snapshot,
    CloudSessionRemoteRecord record,
  ) => snapshot.localPaths[record.parentSessionId];

  static List<CloudSessionRemoteRecord> _parentsFirst(
    Iterable<CloudSessionRemoteRecord> input,
  ) {
    final remaining = input.toList();
    final result = <CloudSessionRemoteRecord>[];
    final seen = <String>{};
    while (remaining.isNotEmpty) {
      final index = remaining.indexWhere(
        (record) =>
            record.parentSessionId == null ||
            seen.contains(record.parentSessionId),
      );
      if (index < 0) {
        // Closed/missing parents are a supported local-only exception; retain
        // deterministic input order instead of deadlocking the walk.
        result.addAll(remaining);
        break;
      }
      final record = remaining.removeAt(index);
      seen.add(record.sessionId);
      result.add(record);
    }
    return result;
  }

  static String _operationId() =>
      'session-op-${DateTime.now().microsecondsSinceEpoch}';
  static String _parentPath(String path) =>
      path.contains('/') ? path.substring(0, path.lastIndexOf('/')) : '.';
}

final class _ParsedDocument {
  const _ParsedDocument(this.header, this.records, this.lines);
  final SessionHeader header;
  final List<SessionRecord> records;
  final List<String> lines;
}

void _validateDocument(Uint8List bytes, {required String expectedId}) {
  final parsed = _parse(bytes);
  if (parsed.header.id != expectedId) {
    throw const FormatException('cloud session id/header mismatch');
  }
}

SessionHeader sessionDocumentHeader(Uint8List bytes) => _parse(bytes).header;

/// Merges the record-id union and optionally moves the active pointer to the
/// remote leaf with an explicit sync marker. No timestamps are compared.
Uint8List mergeSessionJsonl(
  Uint8List localBytes,
  Uint8List remoteBytes, {
  String? parentSessionPath,
  bool preferRemoteLeaf = false,
}) {
  final local = _parse(localBytes);
  final remote = _parse(remoteBytes);
  if (local.header.id != remote.header.id) {
    throw const FormatException('cannot merge different session ids');
  }
  final header = SessionHeader(
    id: local.header.id,
    timestamp: local.header.timestamp,
    cwd: local.header.cwd,
    parentSessionPath: parentSessionPath ?? local.header.parentSessionPath,
    metadata: local.header.metadata,
  );
  final ids = local.records.map((record) => record.id).toSet();
  final lines = [...local.lines];
  for (var i = 0; i < remote.records.length; i++) {
    if (ids.add(remote.records[i].id)) lines.add(remote.lines[i]);
  }
  if (preferRemoteLeaf &&
      _activeLeaf(local.records) != _activeLeaf(remote.records)) {
    final target = _activeLeaf(remote.records);
    final marker = LeafRecord(
      id: 'cloud-sync-${cryptoSha256(remoteBytes).substring(0, 16)}',
      parentId: target,
      timestamp: DateTime.utc(2026, 1, 1),
      targetId: target,
    );
    if (ids.add(marker.id)) lines.add(jsonEncode(marker.toJson()));
  }
  return Uint8List.fromList(
    utf8.encode('${jsonEncode(header.toJson())}\n${lines.join('\n')}\n'),
  );
}

Uint8List _rewriteParent(Uint8List bytes, String? parentPath) {
  final parsed = _parse(bytes);
  final header = SessionHeader(
    id: parsed.header.id,
    timestamp: parsed.header.timestamp,
    cwd: parsed.header.cwd,
    parentSessionPath: parentPath,
    metadata: parsed.header.metadata,
  );
  return Uint8List.fromList(
    utf8.encode('${jsonEncode(header.toJson())}\n${parsed.lines.join('\n')}\n'),
  );
}

String? _activeLeaf(List<SessionRecord> records) {
  String? leaf;
  for (final record in records) {
    leaf = leafIdAfterSessionRecord(record);
  }
  return leaf;
}

_ParsedDocument _parse(Uint8List bytes) {
  final source = utf8.decode(bytes);
  final lines = const LineSplitter().convert(source);
  if (lines.isEmpty) throw const FormatException('empty cloud session');
  final header = SessionHeader.fromJson(
    (jsonDecode(lines.first) as Map).cast<String, dynamic>(),
  );
  final records = <SessionRecord>[];
  final recordLines = <String>[];
  for (final line in lines.skip(1)) {
    if (line.trim().isEmpty) continue;
    records.add(
      SessionRecord.fromJson((jsonDecode(line) as Map).cast<String, dynamic>()),
    );
    recordLines.add(line);
  }
  return _ParsedDocument(header, records, recordLines);
}

import 'dart:convert';
import 'dart:typed_data';

import 'package:crypto/crypto.dart';

import '../product/fa_product_config.dart';
import 'drive_contract.dart';

final class CloudSessionScope {
  const CloudSessionScope({
    required this.providerId,
    required this.connectionId,
    required this.identity,
  });

  final String providerId;
  final String connectionId;
  final CloudIdentity identity;

  String get scopeKey {
    identity.validate();
    return sha256
        .convert(
          utf8.encode(
            '$providerId\u0000$connectionId\u0000${identity.accountKey}',
          ),
        )
        .toString();
  }

  bool accepts(CloudIdentity candidate) => identity.canWriteFor(candidate);
}

final class CloudSessionRemoteRecord {
  const CloudSessionRemoteRecord({
    required this.sessionId,
    required this.parentSessionId,
    required this.revision,
    required this.sha256,
    required this.size,
    this.deleted = false,
  });

  final String sessionId;
  final String? parentSessionId;
  final String revision;
  final String? sha256;
  final int size;
  final bool deleted;
}

final class CloudSessionDownload {
  const CloudSessionDownload({required this.record, required this.bytes});
  final CloudSessionRemoteRecord record;
  final Uint8List bytes;
}

final class CloudSessionUpload {
  CloudSessionUpload({
    required this.scope,
    required this.sessionId,
    required this.parentSessionId,
    required this.bytes,
    required this.operationId,
    required this.baseRevision,
    required this.authGeneration,
  }) : sha256 = cryptoSha256(bytes);

  final CloudSessionScope scope;
  final String sessionId;
  final String? parentSessionId;
  final Uint8List bytes;
  final String operationId;
  final String? baseRevision;
  final int authGeneration;
  final String sha256;

  String get fingerprint => cryptoSha256(
    utf8.encode(
      '${scope.scopeKey}\n$sessionId\n$sha256\n${baseRevision ?? ''}\n${parentSessionId ?? ''}',
    ),
  );
}

final class CloudSessionPage {
  const CloudSessionPage({
    required this.records,
    this.nextCursor,
    this.hasMore = false,
  });
  final List<CloudSessionRemoteRecord> records;
  final String? nextCursor;
  final bool hasMore;
}

abstract interface class RemoteSessionProvider {
  String get providerId;
  Future<DriveResult<CloudSessionPage>> list(
    CloudSessionScope scope,
    String? cursor,
  );
  Future<DriveResult<CloudSessionDownload>> download(
    CloudSessionScope scope,
    String sessionId,
  );
  Future<DriveResult<CloudSessionRemoteRecord>> upload(
    CloudSessionUpload upload,
  );
  Future<DriveResult<CloudSessionRemoteRecord>> delete(
    CloudSessionScope scope,
    String sessionId,
    String operationId,
    String? baseRevision,
    int authGeneration,
  );
}

/// Validated, read-only share grant returned by a host backend. The link
/// carries expiry and server-side read caps, never account/cache credentials.
final class CloudSessionShareLink {
  factory CloudSessionShareLink.parse(
    Uri uri, {
    required Set<String> allowedHosts,
    DateTime? now,
  }) {
    final segments = uri.pathSegments;
    final query = uri.queryParameters;
    final capabilities = (query['capabilities'] ?? 'read')
        .split(',')
        .where((value) => value.isNotEmpty)
        .toSet();
    final expiry = DateTime.tryParse(query['expires'] ?? '');
    final maxReads = int.tryParse(query['maxReads'] ?? '');
    if (uri.scheme != 'https' ||
        uri.hasFragment ||
        uri.userInfo.isNotEmpty ||
        !allowedHosts.contains(uri.host) ||
        segments.length != 3 ||
        segments[0] != 'share' ||
        segments[1] != 'sessions' ||
        !RegExp(r'^[A-Za-z0-9-]{6,64}$').hasMatch(segments[2]) ||
        expiry == null ||
        maxReads == null ||
        maxReads < 1 ||
        maxReads > 10000 ||
        !capabilities.every((capability) => capability == 'read') ||
        query.keys.any(
          (key) => !const {'expires', 'maxReads', 'capabilities'}.contains(key),
        )) {
      throw const FormatException(
        'invalid cloud session share link/capabilities',
      );
    }
    return CloudSessionShareLink._(
      uri,
      segments[2],
      expiry.toUtc(),
      maxReads,
      Set.unmodifiable(capabilities),
    );
  }

  const CloudSessionShareLink._(
    this.uri,
    this.sessionId,
    this.expiresAt,
    this.maxReads,
    this.capabilities,
  );

  final Uri uri;
  final String sessionId;
  final DateTime expiresAt;
  final int maxReads;
  final Set<String> capabilities;

  bool allowsReadAt(DateTime instant) =>
      capabilities.contains('read') && instant.toUtc().isBefore(expiresAt);
}

final class CloudSessionOperation {
  const CloudSessionOperation({
    required this.sessionId,
    required this.parentSessionId,
    required this.localPath,
    required this.bytes,
    required this.operationId,
    required this.baseRevision,
    required this.authGeneration,
    required this.createdAt,
    this.delete = false,
  });

  final String sessionId;
  final String? parentSessionId;
  final String localPath;
  final Uint8List bytes;
  final String operationId;
  final String? baseRevision;
  final int authGeneration;
  final DateTime createdAt;
  final bool delete;

  CloudSessionOperation copyWith({
    Uint8List? bytes,
    String? operationId,
    String? baseRevision,
    int? authGeneration,
  }) => CloudSessionOperation(
    sessionId: sessionId,
    parentSessionId: parentSessionId,
    localPath: localPath,
    bytes: bytes ?? this.bytes,
    operationId: operationId ?? this.operationId,
    baseRevision: baseRevision ?? this.baseRevision,
    authGeneration: authGeneration ?? this.authGeneration,
    createdAt: createdAt,
    delete: delete,
  );

  Map<String, Object?> toJson() => {
    'sessionId': sessionId,
    'parentSessionId': parentSessionId,
    'localPath': localPath,
    'bytes': base64Encode(bytes),
    'operationId': operationId,
    'baseRevision': baseRevision,
    'authGeneration': authGeneration,
    'createdAt': createdAt.toUtc().toIso8601String(),
    'delete': delete,
  };

  factory CloudSessionOperation.fromJson(Map<String, Object?> json) {
    final bytes = Uint8List.fromList(base64Decode(json['bytes']! as String));
    return CloudSessionOperation(
      sessionId: json['sessionId']! as String,
      parentSessionId: json['parentSessionId'] as String?,
      localPath: json['localPath']! as String,
      bytes: bytes,
      operationId: json['operationId']! as String,
      baseRevision: json['baseRevision'] as String?,
      authGeneration: json['authGeneration']! as int,
      createdAt: DateTime.parse(json['createdAt']! as String).toUtc(),
      delete: json['delete']! as bool,
    );
  }
}

final class CloudSessionSnapshot {
  const CloudSessionSnapshot({
    required this.scopeKey,
    required this.storageRevision,
    required this.pending,
    required this.remoteRevisions,
    required this.localPaths,
    this.cursor,
  });

  factory CloudSessionSnapshot.empty(String scopeKey) => CloudSessionSnapshot(
    scopeKey: scopeKey,
    storageRevision: 0,
    pending: const [],
    remoteRevisions: const {},
    localPaths: const {},
  );

  final String scopeKey;
  final int storageRevision;
  final List<CloudSessionOperation> pending;
  final Map<String, String> remoteRevisions;
  final Map<String, String> localPaths;
  final String? cursor;

  CloudSessionSnapshot copyWith({
    List<CloudSessionOperation>? pending,
    Map<String, String>? remoteRevisions,
    Map<String, String>? localPaths,
    String? cursor,
  }) => CloudSessionSnapshot(
    scopeKey: scopeKey,
    storageRevision: storageRevision,
    pending: pending ?? this.pending,
    remoteRevisions: remoteRevisions ?? this.remoteRevisions,
    localPaths: localPaths ?? this.localPaths,
    cursor: cursor ?? this.cursor,
  );

  Map<String, Object?> payloadJson() => {
    'schemaVersion': 1,
    'scopeKey': scopeKey,
    'pending': pending.map((op) => op.toJson()).toList(),
    'remoteRevisions': remoteRevisions,
    'localPaths': localPaths,
    'cursor': cursor,
  };

  factory CloudSessionSnapshot.fromPayload(
    Map<String, Object?> json, {
    required int storageRevision,
  }) {
    if (json['schemaVersion'] != 1) {
      throw const FormatException('unsupported cloud session snapshot');
    }
    return CloudSessionSnapshot(
      scopeKey: json['scopeKey']! as String,
      storageRevision: storageRevision,
      pending: (json['pending']! as List)
          .map(
            (raw) => CloudSessionOperation.fromJson(
              (raw as Map).cast<String, Object?>(),
            ),
          )
          .toList(),
      remoteRevisions: (json['remoteRevisions']! as Map).cast<String, String>(),
      localPaths: (json['localPaths']! as Map).cast<String, String>(),
      cursor: json['cursor'] as String?,
    );
  }
}

final class CloudSessionStoreConcurrencyException implements Exception {
  const CloudSessionStoreConcurrencyException(this.scopeKey);
  final String scopeKey;
}

abstract interface class CloudSessionSyncStore {
  Future<CloudSessionSnapshot> load(String scopeKey);
  Future<CloudSessionSnapshot> save(
    CloudSessionSnapshot snapshot, {
    required int expectedStorageRevision,
  });
}

final class MemoryCloudSessionSyncStore implements CloudSessionSyncStore {
  final Map<String, Map<String, Object?>> _records = {};

  @override
  Future<CloudSessionSnapshot> load(String scopeKey) async {
    final record = _records[scopeKey];
    if (record == null) return CloudSessionSnapshot.empty(scopeKey);
    return CloudSessionSnapshot.fromPayload(
      _clone((record['payload']! as Map).cast<String, Object?>()),
      storageRevision: record['storageRevision']! as int,
    );
  }

  @override
  Future<CloudSessionSnapshot> save(
    CloudSessionSnapshot snapshot, {
    required int expectedStorageRevision,
  }) async {
    final current =
        _records[snapshot.scopeKey]?['storageRevision'] as int? ?? 0;
    if (current != expectedStorageRevision ||
        snapshot.storageRevision != expectedStorageRevision) {
      throw CloudSessionStoreConcurrencyException(snapshot.scopeKey);
    }
    final revision = expectedStorageRevision + 1;
    final payload = _clone(snapshot.payloadJson());
    _records[snapshot.scopeKey] = {
      'storageRevision': revision,
      'payload': payload,
    };
    return CloudSessionSnapshot.fromPayload(
      _clone(payload),
      storageRevision: revision,
    );
  }

  static Map<String, Object?> _clone(Map<String, Object?> value) =>
      (jsonDecode(jsonEncode(value)) as Map).cast<String, Object?>();
}

import 'dart:async';

import '../exceptions.dart';
import '../session/session_record.dart';
import '../session/session_repo.dart';
import '../session/session_storage.dart';
import '../session/session_tree.dart';
import 'cloud_session_synchronizer.dart';

/// SessionRepo decorator: every local operation completes first. Cloud work
/// rides the storage append hook and an explicit background flush/pull.
final class CloudSessionRepo implements SessionRepo {
  const CloudSessionRepo(this.local, this.synchronizer);

  final SessionRepo local;
  final CloudSessionSynchronizer synchronizer;

  @override
  Future<Session> create(JsonlSessionCreateOptions options) async {
    final session = await local.create(options);
    final metadata = await session.getMetadata();
    _markDirty(metadata);
    return _wrap(session, metadata);
  }

  @override
  Future<Session> open(
    SessionMetadata metadata, {
    bool windowed = false,
    bool wholeFileOnly = false,
  }) async {
    try {
      final session = await local.open(
        metadata,
        windowed: windowed,
        wholeFileOnly: wholeFileOnly,
      );
      return _wrap(session, await session.getMetadata());
    } on SessionException catch (error) {
      if (error.code != SessionErrorCode.notFound) rethrow;
      await synchronizer
          .pull(synchronizer.scope.identity)
          .timeout(synchronizer.remoteReadTimeout);
      final localMetadata = await synchronizer.localMetadata(metadata.id);
      if (localMetadata == null) rethrow;
      final session = await local.open(
        localMetadata,
        windowed: windowed,
        wholeFileOnly: wholeFileOnly,
      );
      return _wrap(session, await session.getMetadata());
    }
  }

  @override
  Future<List<SessionMetadata>> list({String? cwd}) => local.list(cwd: cwd);

  /// Local delete stays local by design: closing a branch on one device must
  /// not tombstone a shared tree on every other device.
  @override
  Future<void> delete(SessionMetadata metadata, {String actor = 'unknown'}) =>
      local.delete(metadata, actor: actor);

  /// Explicit opt-in remote tombstone, separate from local delete.
  Future<void> closeRemoteBranch(SessionMetadata metadata) =>
      synchronizer.enqueueRemoteDelete(metadata);

  @override
  Future<Session> fork(
    SessionMetadata source, {
    required String cwd,
    String? entryId,
    ForkPosition position = ForkPosition.before,
    String? id,
    String? parentSessionPath,
    Map<String, dynamic>? metadata,
  }) async {
    final session = await local.fork(
      source,
      cwd: cwd,
      entryId: entryId,
      position: position,
      id: id,
      parentSessionPath: parentSessionPath,
      metadata: metadata,
    );
    final forked = await session.getMetadata();
    _markDirty(forked, parentSessionId: source.id);
    return _wrap(session, forked);
  }

  Session _wrap(Session session, SessionMetadata metadata) =>
      session.decorateStorage(
        (storage) =>
            CloudSessionStorage(storage, onChanged: () => _markDirty(metadata)),
      );

  void _markDirty(SessionMetadata metadata, {String? parentSessionId}) {
    unawaited(
      synchronizer.markDirty(metadata, parentSessionId: parentSessionId),
    );
  }
}

final class CloudSessionStorage implements SessionStorage {
  const CloudSessionStorage(this.delegate, {required this.onChanged});

  final SessionStorage delegate;
  final void Function() onChanged;

  @override
  Future<void> appendEntry(SessionRecord record) async {
    await delegate.appendEntry(record);
    onChanged();
  }

  @override
  Future<void> setLeafId(String? leafId) async {
    await delegate.setLeafId(leafId);
    onChanged();
  }

  @override
  Future<String> createEntryId() => delegate.createEntryId();
  @override
  Future<List<SessionRecord>> findEntries(String type) =>
      delegate.findEntries(type);
  @override
  Future<SessionRecord?> getEntry(String id) => delegate.getEntry(id);
  @override
  Future<List<SessionRecord>> getEntries() => delegate.getEntries();
  @override
  Future<String?> getLabel(String id) => delegate.getLabel(id);
  @override
  Future<String?> getLeafId() => delegate.getLeafId();
  @override
  Future<SessionMetadata> getMetadata() => delegate.getMetadata();
  @override
  Future<List<SessionRecord>> getPathToRoot(String? leafId) =>
      delegate.getPathToRoot(leafId);
}

import 'drive_contract.dart';

enum CloudProviderReadinessLevel { stub, mvp, complete }

/// Host-facing readiness assessment. Missing delta support is an MVP full-scan
/// fallback, never a reason to claim complete synchronization.
final class CloudProviderReadiness {
  const CloudProviderReadiness({
    required this.capabilities,
    required this.planEnabled,
    required this.featureAllowed,
    required this.usedBytes,
    required this.quotaBytes,
  });

  final DriveCapabilities capabilities;
  final bool planEnabled;
  final bool featureAllowed;
  final int usedBytes;
  final int quotaBytes;

  CloudProviderReadinessLevel get level {
    if (capabilities.maxFileBytes <= 0 ||
        !capabilities.conditionalWrites ||
        !capabilities.revisions) {
      return CloudProviderReadinessLevel.stub;
    }
    if (!capabilities.deltaCursors || !capabilities.hashes) {
      return CloudProviderReadinessLevel.mvp;
    }
    return CloudProviderReadinessLevel.complete;
  }

  bool get requiresFullScan => !capabilities.deltaCursors;
  bool get onlineWritesAllowed =>
      planEnabled &&
      featureAllowed &&
      level != CloudProviderReadinessLevel.stub;
  int? get remainingBytes => quotaBytes < 0 ? null : quotaBytes - usedBytes;

  void validateUpload(int size) {
    if (!planEnabled) {
      throw const DriveProviderException(
        DriveErrorKind.inactivePlan,
        'cloud sync is not enabled for this account plan',
      );
    }
    if (!featureAllowed) {
      throw const DriveProviderException(
        DriveErrorKind.featureDenied,
        'cloud sync is denied for this account',
      );
    }
    if (size < 0 || size > capabilities.maxFileBytes) {
      throw DriveProviderException(
        DriveErrorKind.quotaExceeded,
        'file exceeds the provider size limit',
      );
    }
    final remaining = remainingBytes;
    if (remaining != null && size > remaining) {
      throw const DriveProviderException(
        DriveErrorKind.quotaExceeded,
        'account cloud quota exhausted',
      );
    }
  }
}

/// Deterministic HTTP/provider payload mapping shared by host adapters.
final class CloudProviderErrorMapper {
  const CloudProviderErrorMapper._();

  static DriveProviderException fromResponse({
    required int statusCode,
    String? providerCode,
    String? message,
    String? retryAfter,
    String? providerOperationId,
  }) {
    final code = providerCode?.toLowerCase();
    final inactivePlan =
        statusCode == 403 &&
        const {'inactive_plan', 'plan_required'}.contains(code);
    final kind = inactivePlan
        ? DriveErrorKind.inactivePlan
        : _httpErrorKinds[statusCode] ??
              (statusCode >= 500 && statusCode <= 599
                  ? DriveErrorKind.transient
                  : DriveErrorKind.permanent);
    return DriveProviderException(
      kind,
      message ?? 'provider HTTP $statusCode',
      retryAfter: _retryAfter(retryAfter),
      providerOperationId: providerOperationId,
      statusCode: statusCode,
    );
  }

  static RemoteDriveItem itemFromJson(
    Map<String, Object?> json, {
    Set<String> aliases = const {},
  }) {
    try {
      final path = DrivePath.parse(json['path']! as String, aliases: aliases);
      final revision = json['revision']! as String;
      final hash = json['sha256'] as String?;
      final size = json['size']! as int;
      final modified = DateTime.parse(json['modifiedAt']! as String).toUtc();
      if (revision.isEmpty ||
          size < 0 ||
          (hash != null && !_sha.hasMatch(hash))) {
        throw const FormatException('invalid revision/hash/size');
      }
      return RemoteDriveItem(
        path: path,
        revision: revision,
        sha256: hash,
        size: size,
        modifiedAt: modified,
        isDirectory: json['isDirectory'] == true,
        deleted: json['deleted'] == true,
        etag: json['etag'] as String?,
      );
    } catch (error) {
      throw DriveProviderException(
        DriveErrorKind.invalidResponse,
        'invalid drive item payload',
        cause: error,
      );
    }
  }

  static DriveChangesPage changesFromJson(
    Map<String, Object?> json, {
    Set<String> aliases = const {},
  }) {
    try {
      final hasMore = json['hasMore'] == true;
      final cursor = json['nextCursor'] as String?;
      if (hasMore && (cursor == null || cursor.isEmpty)) {
        throw const FormatException('missing delta cursor');
      }
      return DriveChangesPage(
        items: (json['items']! as List)
            .map(
              (raw) => itemFromJson(
                (raw as Map).cast<String, Object?>(),
                aliases: aliases,
              ),
            )
            .toList(),
        nextCursor: cursor,
        hasMore: hasMore,
      );
    } on DriveProviderException {
      rethrow;
    } catch (error) {
      throw DriveProviderException(
        DriveErrorKind.invalidResponse,
        'invalid drive changes payload',
        cause: error,
      );
    }
  }

  static const _httpErrorKinds = <int, DriveErrorKind>{
    401: DriveErrorKind.providerReauthRequired,
    402: DriveErrorKind.inactivePlan,
    403: DriveErrorKind.featureDenied,
    404: DriveErrorKind.notFound,
    409: DriveErrorKind.preconditionFailed,
    412: DriveErrorKind.preconditionFailed,
    413: DriveErrorKind.quotaExceeded,
    429: DriveErrorKind.rateLimited,
    507: DriveErrorKind.quotaExceeded,
  };

  static Duration? _retryAfter(String? value) {
    final seconds = value == null ? null : int.tryParse(value);
    return seconds == null || seconds < 0 ? null : Duration(seconds: seconds);
  }

  static final RegExp _sha = RegExp(r'^[a-fA-F0-9]{64}$');
}

/// Explicit no-backend provider for host wiring/tests. It performs no network
/// and always reports featureDenied instead of pretending to synchronize.
final class StubRemoteDriveProvider implements RemoteDriveProvider {
  const StubRemoteDriveProvider(this.providerId);

  @override
  final String providerId;
  @override
  DriveCapabilities get capabilities => const DriveCapabilities.none();

  DriveResult<T> _denied<T>() => const DriveResult.failure(
    DriveProviderException(
      DriveErrorKind.featureDenied,
      'stub provider has no live backend',
    ),
  );

  @override
  Future<DriveResult<DriveChangesPage>> changes(
    DriveChangesRequest request,
  ) async => _denied();
  @override
  Future<DriveResult<RemoteDriveItem>> delete(
    DriveDeleteRequest request,
  ) async => _denied();
  @override
  Future<DriveResult<RemoteDriveDownload>> download(
    DriveMountScope scope,
    DrivePath path,
  ) async => _denied();
  @override
  Future<DriveResult<RemoteDriveItem>> get(
    DriveMountScope scope,
    DrivePath path,
  ) async => _denied();
  @override
  Future<DriveResult<List<RemoteDriveItem>>> list(
    DriveListRequest request,
  ) async => _denied();
  @override
  Future<DriveResult<RemoteDriveItem>> upload(
    DriveUploadRequest request,
  ) async => _denied();
}

import 'dart:convert';

import 'package:crypto/crypto.dart';

/// Immutable, host-supplied product identity for a branded Fa workspace.
///
/// The harness ships no product backends or credentials. [stock] is the only
/// configuration that preserves legacy browser storage keys and it can never
/// enable cloud synchronization. Any explicitly supplied profile is branded,
/// including one whose id happens to be `fa`.
final class FaProductConfig {
  const FaProductConfig({
    required this.productId,
    required this.displayName,
    this.description = '',
    this.brandAssets = const {},
    this.themePackId,
    this.themePack,
    this.authEndpoint,
    this.apiEndpoint,
    this.driveEndpoint,
    this.sessionEndpoint,
    this.oauthCallback,
    this.legalLinks = const {},
    this.featureFlags = const {},
    this.driveAliases = const {},
    this.storageSchemaVersion = 1,
  }) : _stock = false;

  const FaProductConfig._stock()
    : productId = 'fa',
      displayName = 'Fa',
      description = 'Fa — Flutter Agent Harness: coding agent in your browser.',
      brandAssets = const {},
      themePackId = null,
      themePack = null,
      authEndpoint = null,
      apiEndpoint = null,
      driveEndpoint = null,
      sessionEndpoint = null,
      oauthCallback = null,
      legalLinks = const {},
      featureFlags = const {},
      driveAliases = const {},
      storageSchemaVersion = 1,
      _stock = true;

  /// Default Fa identity. No profile file is required to retain this behavior.
  static const stock = FaProductConfig._stock();

  final String productId;
  final String displayName;
  final String description;

  /// Logical asset slot (`icon192`, `icon512`, `favicon`, `splash`, …) to a
  /// normalized relative path inside the host's external asset directory.
  final Map<String, String> brandAssets;
  final String? themePackId;
  final Map<String, Object?>? themePack;
  final Uri? authEndpoint;
  final Uri? apiEndpoint;
  final Uri? driveEndpoint;
  final Uri? sessionEndpoint;
  final Uri? oauthCallback;
  final Map<String, Uri> legalLinks;
  final Set<String> featureFlags;
  final Set<String> driveAliases;
  final int storageSchemaVersion;
  final bool _stock;

  bool get isStock => _stock;

  /// Cloud work requires BOTH an explicit flag and a real endpoint. Merely
  /// parsing a product profile never registers a provider or starts sync.
  bool get cloudSyncEnabled =>
      !_stock &&
      featureFlags.contains('cloudSync') &&
      (driveEndpoint != null || sessionEndpoint != null);

  /// Product/schema storage namespace. `null` is the compatibility sentinel:
  /// browser stores keep their pre-product legacy keys for stock Fa.
  String? storageNamespace(int schema) {
    if (schema < 1) throw ArgumentError.value(schema, 'schema');
    return _stock ? null : 'fa-product:$productId:schema:$schema';
  }

  /// Account partition below [storageNamespace], keyed by the verified
  /// immutable tenant+subject. Device id and auth generation fence work but do
  /// not silently move an account's existing local cache on re-authentication.
  String accountNamespace(CloudIdentity identity, int schema) {
    identity.validate();
    final product = storageNamespace(schema);
    if (product == null) {
      throw StateError('stock Fa has no account cloud namespace');
    }
    return '$product:account:${identity.accountKey}';
  }

  /// Exact callback matching plus non-empty state validation. Host auth
  /// coordinators call this instead of growing product-specific forks.
  bool acceptsOAuthCallback(
    Uri callback, {
    required String expectedState,
    required String? receivedState,
  }) {
    final expected = oauthCallback;
    return expected != null &&
        callback == expected &&
        expectedState.isNotEmpty &&
        receivedState == expectedState;
  }

  /// Parses and validates an external JSON profile. Unknown fields are
  /// tolerated for forward compatibility, but credential-shaped fields are
  /// rejected recursively so secrets cannot hide in extension metadata.
  factory FaProductConfig.fromJson(Map<String, Object?> json) {
    _rejectSecretFields(json);
    final productId = _id(json['productId'], 'productId');
    final displayName = _text(json['displayName'], 'displayName');
    final description = json['description'] == null
        ? ''
        : _text(json['description'], 'description', allowEmpty: true);
    final themePackId = json['themePackId'] == null
        ? null
        : _id(json['themePackId'], 'themePackId');
    final assets = <String, String>{};
    final rawAssets = json['brandAssets'];
    if (rawAssets != null) {
      if (rawAssets is! Map) throw const FormatException('brandAssets map');
      for (final entry in rawAssets.entries) {
        final slot = _id(entry.key, 'brandAssets slot');
        assets[slot] = _assetPath(entry.value);
      }
    }
    Uri? endpoint(String name) {
      final value = json[name];
      if (value == null) return null;
      if (value is! String) throw FormatException('$name must be a URI');
      final uri = Uri.tryParse(value);
      if (uri == null || !_secureEndpoint(uri)) {
        throw FormatException('$name must be an HTTPS endpoint: $value');
      }
      return uri;
    }

    final legal = <String, Uri>{};
    final rawLegal = json['legalLinks'];
    if (rawLegal != null) {
      if (rawLegal is! Map) throw const FormatException('legalLinks map');
      for (final entry in rawLegal.entries) {
        final key = _id(entry.key, 'legalLinks key');
        final uri = Uri.tryParse(entry.value.toString());
        if (uri == null || !_secureEndpoint(uri)) {
          throw FormatException('legal link $key must use HTTPS');
        }
        legal[key] = uri;
      }
    }
    final flags = <String>{};
    final rawFlags = json['featureFlags'];
    if (rawFlags != null) {
      if (rawFlags is! List) throw const FormatException('featureFlags list');
      for (final flag in rawFlags) {
        flags.add(_featureFlag(flag));
      }
    }
    final aliases = <String>{};
    final rawAliases = json['driveAliases'];
    if (rawAliases != null) {
      if (rawAliases is! List) throw const FormatException('driveAliases list');
      for (final alias in rawAliases) {
        if (alias is! String ||
            !RegExp(r'^/[a-z][a-z0-9_-]{0,63}$').hasMatch(alias) ||
            const {
              '/drive',
              '/.dap',
              '/.env',
              '/logs',
              '/oauth',
            }.contains(alias)) {
          throw const FormatException('invalid drive alias');
        }
        aliases.add(alias);
      }
    }
    final schema = json['storageSchemaVersion'] ?? 1;
    if (schema is! int || schema < 1 || schema > 100) {
      throw const FormatException('storageSchemaVersion must be 1..100');
    }
    final rawThemePack = json['themePack'];
    Map<String, Object?>? themePack;
    if (rawThemePack != null) {
      if (rawThemePack is! Map ||
          rawThemePack['name'] is! String ||
          rawThemePack['version'] is! String ||
          rawThemePack['colors'] is! Map ||
          rawThemePack.containsKey('wallpaper') ||
          rawThemePack.keys.any(
            (key) =>
                const {'code', 'script', 'js', 'url', 'asset'}.contains(key),
          )) {
        throw const FormatException('invalid declarative host themePack');
      }
      themePack = rawThemePack.cast<String, Object?>();
    }
    if (themePack != null && themePackId == null) {
      throw const FormatException('themePack requires themePackId');
    }
    if (themePack != null) {
      final slug = (themePack['name']! as String)
          .trim()
          .toLowerCase()
          .replaceAll(RegExp(r'[^a-z0-9]+'), '-')
          .replaceAll(RegExp(r'^-|-$'), '');
      if (slug != themePackId) {
        throw const FormatException(
          'themePackId must match the theme name slug',
        );
      }
    }
    final config = FaProductConfig(
      productId: productId,
      displayName: displayName,
      description: description,
      brandAssets: Map.unmodifiable(assets),
      themePackId: themePackId,
      themePack: themePack,
      authEndpoint: endpoint('authEndpoint'),
      apiEndpoint: endpoint('apiEndpoint'),
      driveEndpoint: endpoint('driveEndpoint'),
      sessionEndpoint: endpoint('sessionEndpoint'),
      oauthCallback: endpoint('oauthCallback'),
      legalLinks: Map.unmodifiable(legal),
      featureFlags: Set.unmodifiable(flags),
      driveAliases: Set.unmodifiable(aliases),
      storageSchemaVersion: schema,
    );
    if (config.oauthCallback != null && config.authEndpoint == null) {
      throw const FormatException('oauthCallback requires authEndpoint');
    }
    return config;
  }

  static bool _secureEndpoint(Uri uri) {
    if (!uri.hasScheme || uri.host.isEmpty || uri.hasFragment) return false;
    if (uri.scheme == 'https') return true;
    return uri.scheme == 'http' &&
        (uri.host == 'localhost' ||
            uri.host == '127.0.0.1' ||
            uri.host == '[::1]' ||
            uri.host == '::1');
  }

  static String _id(Object? value, String name) {
    if (value is! String ||
        !RegExp(r'^[a-z][a-z0-9._-]{0,63}$').hasMatch(value)) {
      throw FormatException('$name must be a lowercase stable id');
    }
    return value;
  }

  static String _featureFlag(Object? value) {
    if (value is! String ||
        !RegExp(r'^[A-Za-z][A-Za-z0-9._-]{0,63}$').hasMatch(value)) {
      throw const FormatException('feature flag must be a stable id');
    }
    return value;
  }

  static String _text(Object? value, String name, {bool allowEmpty = false}) {
    if (value is! String ||
        (!allowEmpty && value.trim().isEmpty) ||
        value.contains(RegExp(r'[<>\x00-\x1f\x7f]'))) {
      throw FormatException('$name contains unsafe text');
    }
    return value;
  }

  static String _assetPath(Object? value) {
    if (value is! String || value.isEmpty) {
      throw const FormatException('asset path must be a string');
    }
    if (value.startsWith('/') ||
        value.contains('\\') ||
        value.contains(RegExp(r'[\x00-\x1f\x7f]'))) {
      throw const FormatException('asset path must be relative POSIX');
    }
    final parts = value.split('/');
    if (parts.any((part) => part.isEmpty || part == '.' || part == '..')) {
      throw FormatException('invalid asset path: $value');
    }
    return parts.join('/');
  }

  static void _rejectSecretFields(Object? value) {
    if (value is Map) {
      for (final entry in value.entries) {
        final key = entry.key.toString().toLowerCase().replaceAll(
          RegExp('[^a-z]'),
          '',
        );
        if (key.contains('apikey') ||
            key.contains('token') ||
            key.contains('password') ||
            key.contains('secret') ||
            key == 'credential' ||
            key == 'credentials') {
          throw FormatException('credential field forbidden: ${entry.key}');
        }
        _rejectSecretFields(entry.value);
      }
    } else if (value is List) {
      for (final item in value) {
        _rejectSecretFields(item);
      }
    }
  }
}

/// Verified account/device identity supplied by the host auth layer.
final class CloudIdentity {
  const CloudIdentity({
    required this.tenantId,
    required this.subject,
    required this.deviceId,
    required this.authGeneration,
  });

  final String tenantId;

  /// Immutable issuer subject, never an email address or display name.
  final String subject;
  final String deviceId;
  final int authGeneration;

  void validate() {
    for (final (name, value) in [
      ('tenantId', tenantId),
      ('subject', subject),
      ('deviceId', deviceId),
    ]) {
      if (value.isEmpty || value.contains(RegExp(r'[\x00-\x1f\x7f]'))) {
        throw FormatException('$name is invalid');
      }
    }
    if (subject.contains('@')) {
      throw const FormatException('subject must be immutable, never email');
    }
    if (authGeneration < 1) {
      throw ArgumentError.value(authGeneration, 'authGeneration');
    }
  }

  /// Stable local account key. Raw tenant/subject values are not exposed as
  /// IndexedDB, service-worker, or cache names.
  String get accountKey {
    validate();
    return sha256
        .convert(utf8.encode('tenant\u0000$tenantId\nsubject\u0000$subject'))
        .toString();
  }

  /// True only for the same live writer fence. Sign-out/account switch must
  /// advance [authGeneration], making every older in-flight operation stale.
  bool canWriteFor(CloudIdentity active) {
    validate();
    active.validate();
    return tenantId == active.tenantId &&
        subject =[REDACTED:Certificate-DN]
        deviceId == active.deviceId &&
        authGeneration == active.authGeneration;
  }

  CloudIdentity nextGeneration() => CloudIdentity(
    tenantId: tenantId,
    subject: subject,
    deviceId: deviceId,
    authGeneration: authGeneration + 1,
  );
}

import 'dart:async';

import 'fa_product_config.dart';

typedef ProductNamespaceWriter = FutureOr<void> Function(String? namespace);

/// Account-switch boundary for browser storage. The writer closes old DB
/// handles and swaps the namespace synchronously before any new engine work;
/// remote writes are independently fenced by [CloudIdentity.authGeneration].
final class ProductStorageCoordinator {
  ProductStorageCoordinator(this.config, this._writer);

  final FaProductConfig config;
  final ProductNamespaceWriter _writer;
  CloudIdentity? _active;

  CloudIdentity? get active => _active;
  String? get currentNamespace => namespaceFor(_active);

  String? namespaceFor(CloudIdentity? identity) {
    if (config.isStock) return null;
    return identity == null
        ? config.storageNamespace(config.storageSchemaVersion)
        : config.accountNamespace(identity, config.storageSchemaVersion);
  }

  Future<void> activate(CloudIdentity identity) async {
    if (config.isStock) {
      throw StateError('stock Fa has no cloud account storage coordinator');
    }
    identity.validate();
    final previous = _active;
    if (previous != null &&
        previous.tenantId == identity.tenantId &&
        previous.subject =[REDACTED:Certificate-DN]
        identity.authGeneration < previous.authGeneration) {
      throw StateError('auth generation cannot move backwards');
    }
    // Write first: if closing/swapping fails, the old active fence remains.
    await _writer(namespaceFor(identity));
    _active = identity;
  }

  Future<void> signOut() async {
    if (config.isStock) return;
    await _writer(namespaceFor(null));
    _active = null;
  }

  bool permits(CloudIdentity identity) => _active?.canWriteFor(identity) ?? false;
}

